\title{A Fibonacci--Pythagorean Bridge and the Index-Level Law of\\ Strong Divisibility Sequences}
\author{Aristotle}
\date{July 14, 2026}

\begin{document}

\begin{abstract}
We develop two connected strands of elementary number theory and expose the
common structure beneath them. First, we prove a \emph{Fibonacci--Pythagorean
bridge}: from four consecutive Fibonacci numbers $F_n, F_{n+1}, F_{n+2},
F_{n+3}$ one constructs the legs $A = F_n F_{n+3}$ and $B = 2 F_{n+1} F_{n+2}$
and the hypotenuse $C = F_{n+1}^2 + F_{n+2}^2$, obtaining an exact Pythagorean
identity $A^2 + B^2 = C^2$ for every $n$; moreover the hypotenuse is itself a
Fibonacci number, $C = F_{2n+3}$. The two smallest instances reproduce the
classical triples $(3,4,5)$ and $(5,12,13)$. Second, we isolate the abstract
engine behind several classical divisibility laws: for any \emph{strong
divisibility sequence} with distinct terms, term divisibility is equivalent to
index divisibility, $a_m \mid a_n \iff m \mid n$. This single theorem yields the
Fibonacci strong-divisibility law, the Mersenne-type law $a^m - 1 \mid a^n - 1
\iff m \mid n$ for $a \ge 2$, and an index test for Fibonacci primes: if $F_n$
is prime then $n = 4$ or $n$ is prime.
\end{abstract}

\maketitle

\section{Introduction}

The Fibonacci sequence $F_0 = 0$, $F_1 = 1$, $F_{n+2} = F_{n+1} + F_n$ and the
Pythagorean relation $a^2 + b^2 = c^2$ are two of the most heavily studied
objects in elementary mathematics, yet they are usually treated in separate
compartments. A classical construction attributed to Raine and later
systematized by Horadam ties them together: consecutive Fibonacci numbers can be
assembled into Pythagorean triples. This paper gives a clean, fully explicit
account of that bridge and pins down its hypotenuse exactly.

Running underneath the Fibonacci divisibility phenomena is a more general
principle. The Fibonacci numbers form a \emph{strong divisibility sequence}: the
gcd of two terms is the term indexed by the gcd of the indices. So do the
sequences $a^n - 1$. We extract the abstract lemma that makes both work and show
that, for injective strong divisibility sequences, divisibility of terms is
literally divisibility of indices. From this vantage the Fibonacci prime-index
test is a two-line corollary.

\section{Definitions and preliminaries}

\begin{definition}[Fibonacci sequence]
The Fibonacci numbers are defined by $F_0 = 0$, $F_1 = 1$, and $F_{n+2} =
F_{n+1} + F_n$ for all $n \ge 0$. We use the standard facts $F_{n+2} = F_n +
F_{n+1}$ and the addition formula
\begin{equation}
F_{m+k+1} = F_m F_k + F_{m+1} F_{k+1}. \label{eq:add}
\end{equation}
\end{definition}

\begin{definition}[Fibonacci triangle data]
For $n \in \N$ set
\[
A_n = F_n\,F_{n+3},\qquad B_n = 2\,F_{n+1}\,F_{n+2},\qquad C_n = F_{n+1}^2 + F_{n+2}^2.
\]
We call $(A_n, B_n, C_n)$ the \emph{Fibonacci--Pythagorean data at index $n$}.
\end{definition}

\begin{definition}[Strong divisibility sequence]
A sequence $a : \N \to \N$ is a \emph{strong divisibility sequence} if
\begin{equation}
\gcdd(a_m, a_n) = a_{\gcdd(m,n)} \qquad \text{for all } m, n \in \N. \label{eq:sds}
\end{equation}
Every such sequence is a divisibility sequence: if $m \mid n$ then $\gcdd(m,n) =
m$, so $\gcdd(a_m, a_n) = a_m$, i.e. $a_m \mid a_n$.
\end{definition}

\begin{definition}[Pythagorean triple]
A triple $(A, B, C)$ of positive integers is \emph{Pythagorean} if $A^2 + B^2 =
C^2$, and \emph{non-degenerate} if $A, B > 0$.
\end{definition}

\section{The Fibonacci--Pythagorean bridge}

\begin{theorem}[Fibonacci--Pythagorean Identity]\label{thm:pyth}
For every $n \in \N$,
\[
A_n^2 + B_n^2 = C_n^2,
\]
that is, $(F_n F_{n+3})^2 + (2 F_{n+1} F_{n+2})^2 = (F_{n+1}^2 + F_{n+2}^2)^2$.
\end{theorem}

\begin{proof}[Proof sketch]
Write $x = F_n$ and $y = F_{n+1}$. The recurrence gives $F_{n+2} = x + y$ and
$F_{n+3} = x + 2y$. Substituting,
\[
A_n = x^2 + 2xy,\qquad B_n = 2xy + 2y^2,\qquad C_n = x^2 + 2xy + 2y^2.
\]
Expanding both sides as polynomials in $x,y$,
\[
A_n^2 + B_n^2 = x^4 + 4x^3y + 8x^2y^2 + 8xy^3 + 4y^4 = C_n^2,
\]
an identity of polynomials, hence valid for every $n$.
\end{proof}

\begin{theorem}[Fibonacci Hypotenuse Theorem]\label{thm:hyp}
For every $n \in \N$, $\; C_n = F_{n+1}^2 + F_{n+2}^2 = F_{2n+3}$.
\end{theorem}

\begin{proof}[Proof sketch]
Apply \eqref{eq:add} with $m = k = n+1$:
\[
F_{(n+1)+(n+1)+1} = F_{n+1}^2 + F_{n+2}^2,
\]
and $(n+1)+(n+1)+1 = 2n+3$.
\end{proof}

\begin{theorem}[Fibonacci--Pythagorean Triple Theorem]\label{thm:triple}
For every $n \in \N$,
\[
(F_n F_{n+3})^2 + (2 F_{n+1} F_{n+2})^2 = F_{2n+3}^2.
\]
\end{theorem}

\begin{proof}
Combine Theorems~\ref{thm:pyth} and \ref{thm:hyp}: $A_n^2 + B_n^2 = C_n^2 =
F_{2n+3}^2$.
\end{proof}

\begin{theorem}[Non-degeneracy]\label{thm:nondeg}
For every $n \ge 1$, $A_n > 0$ and $B_n > 0$; hence $(A_n, B_n, F_{2n+3})$ is a
genuine non-degenerate right triangle.
\end{theorem}

\begin{proof}[Proof sketch]
For $n \ge 1$ all of $F_n, F_{n+1}, F_{n+2}, F_{n+3}$ are positive, and products
of positive integers are positive.
\end{proof}

\begin{remark}[Primitivity]
The triples need not be primitive; e.g. $n=3$ gives $(16,30,34) =
2\cdot(8,15,17)$. Because $C_n = F_{2n+3}$, the hypotenuses realized are exactly
the odd-index Fibonacci numbers $F_3, F_5, F_7, \dots$
\end{remark}

\section{The index-level law of strong divisibility sequences}

\begin{theorem}[Strong Divisibility Characterization]\label{thm:sdc}
Let $a : \N \to \N$ be a strong divisibility sequence whose terms are distinct
(i.e. $a$ is injective). Then for all $m, n \in \N$,
\[
a_m \mid a_n \quad\Longleftrightarrow\quad m \mid n.
\]
\end{theorem}

\begin{proof}[Proof sketch]
($\Rightarrow$) If $a_m \mid a_n$ then $\gcdd(a_m, a_n) = a_m$; by \eqref{eq:sds}
this equals $a_{\gcdd(m,n)}$, so $a_{\gcdd(m,n)} = a_m$, and injectivity forces
$\gcdd(m,n) = m$, i.e. $m \mid n$.
($\Leftarrow$) If $m \mid n$ then $\gcdd(m,n) = m$, so $\gcdd(a_m, a_n) = a_m$ by
\eqref{eq:sds}, whence $a_m \mid a_n$.
\end{proof}

\begin{corollary}[Fibonacci divisibility law]
On the range of indices where the Fibonacci sequence is strictly increasing,
$F_m \mid F_n \iff m \mid n$. The direction $m \mid n \Rightarrow F_m \mid F_n$
holds for all indices.
\end{corollary}

\begin{theorem}[Mersenne divisibility law]\label{thm:mers}
Fix an integer $a \ge 2$. Then for all $m,n \in \N$,
\[
a^m - 1 \mid a^n - 1 \quad\Longleftrightarrow\quad m \mid n.
\]
\end{theorem}

\begin{proof}[Proof sketch]
The sequence $M_k = a^k - 1$ satisfies $\gcdd(a^m - 1, a^n - 1) = a^{\gcdd(m,n)}
- 1$, so it is a strong divisibility sequence, and for $a \ge 2$ the map $k
\mapsto a^k - 1$ is strictly increasing, hence injective. Apply
Theorem~\ref{thm:sdc}.
\end{proof}

\section{An index test for Fibonacci primes}

\begin{theorem}[Fibonacci Prime Index Test]\label{thm:fptest}
If $F_n$ is prime, then $n = 4$ or $n$ is prime.
\end{theorem}

\begin{proof}[Proof sketch]
If $F_n$ is prime and $n$ is composite with a proper factor $j \ge 3$, then $F_j
\mid F_n$ with $2 \le F_j < F_n$, contradicting primality of $F_n$. The only
composite $n$ all of whose proper nontrivial factors are $\le 2$ is $n = 4$.
\end{proof}

\begin{remark}
$F_4 = 3$ is prime though $4$ is composite, so the exception is genuine. The test
is only necessary: $F_{19} = 4181 = 37\times 113$ is composite though $19$ is
prime.
\end{remark}

\section{Numerics}

\begin{center}
\begin{tabular}{cccc}
\toprule
$n$ & $(A_n, B_n, C_n)$ & $C_n = F_{2n+3}$ & primitive? \\
\midrule
1 & $(3, 4, 5)$       & $F_5 = 5$      & yes \\
2 & $(5, 12, 13)$     & $F_7 = 13$     & yes \\
3 & $(16, 30, 34)$    & $F_9 = 34$     & no  \\
4 & $(39, 80, 89)$    & $F_{11} = 89$  & yes \\
5 & $(105, 208, 233)$ & $F_{13} = 233$ & yes \\
\bottomrule
\end{tabular}
\end{center}

\section{Discussion}

Both strands share a philosophy: rather than verifying an infinite family case by
case, one isolates the single structural fact---a polynomial identity in the
first case, an abstract gcd law in the second---from which the whole family
follows. This lets the Fibonacci and Mersenne divisibility laws be proved
simultaneously as instances of one theorem. Open problems include a uniform
primitive-divisor threshold for injective strong divisibility sequences, the
density of prime indices among Fibonacci primes, a complete parity classification
of Fibonacci hypotenuses, and whether the exceptional index set of a strong
divisibility sequence is an invariant of its growth exponent alone.

\end{document}

