"""Demo: Generate and certify Fibonacci-Pythagorean triples."""
from __future__ import annotations
from math import gcd
from typing import Tuple


def fib(n: int) -> int:
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
    return a


def fib_triple(n: int) -> Tuple[int, int, int]:
    """(A_n, B_n, C_n) = (F_n F_{n+3}, 2 F_{n+1} F_{n+2}, F_{n+1}^2 + F_{n+2}^2)."""
    return (fib(n) * fib(n + 3),
            2 * fib(n + 1) * fib(n + 2),
            fib(n + 1) ** 2 + fib(n + 2) ** 2)


def certify(n: int) -> dict:
    a, b, c = fib_triple(n)
    return {
        "n": n,
        "triple": (a, b, c),
        "pythagorean": a * a + b * b == c * c,
        "hypotenuse_is_F_2n3": c == fib(2 * n + 3),
        "primitive": gcd(gcd(a, b), c) == 1,
    }


if __name__ == "__main__":
    for n in range(1, 9):
        print(certify(n))

"""Demo: Fibonacci prime-index sieve.

Uses the prime-index test (F_n prime => n = 4 or n prime) to prune the
search for Fibonacci primes: only n = 4 and prime n need a primality test.
"""
from __future__ import annotations
from typing import List


def fib(n: int) -> int:
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
    return a


def is_prime(n: int) -> bool:
    if n < 2:
        return False
    d = 2
    while d * d <= n:
        if n % d == 0:
            return False
        d += 1
    return True


def fibonacci_prime_indices(max_idx: int) -> List[int]:
    """Candidate indices n <= max_idx: only 4 and primes, then test F_n."""
    candidates = [4] + [n for n in range(2, max_idx + 1) if is_prime(n)]
    return sorted(n for n in candidates if is_prime(fib(n)))


if __name__ == "__main__":
    print("Fibonacci prime indices up to 50:", fibonacci_prime_indices(50))

