from __future__ import annotations
from typing import Callable


def strong_div_index_test(m: int, n: int) -> bool:
    """For an injective strong divisibility sequence, a_m | a_n  <=>  m | n.

    Returns divisibility of a_m into a_n using only the indices, in O(1)
    arithmetic (no need to materialize the possibly-huge terms).
    """
    if m == 0:
        return True  # a_0 divides everything in the canonical instances
    return n % m == 0


def verify_against_terms(seq: Callable[[int], int], m: int, n: int) -> bool:
    """Sanity check: the index test agrees with the literal term test."""
    return (seq(n) % seq(m) == 0) == strong_div_index_test(m, n)

