from typing import List


def fib(n: int) -> int:
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
    return a


def is_prime(n: int) -> bool:
    if n < 2:
        return False
    d = 2
    while d * d <= n:
        if n % d == 0:
            return False
        d += 1
    return True


def fibonacci_prime_index_sieve(max_idx: int) -> List[int]:
    """Return indices n <= max_idx with F_n prime, using the prime-index test
    (F_n prime => n = 4 or n prime) to restrict primality tests to n = 4 and
    prime n only."""
    candidate_indices = [4] + [n for n in range(2, max_idx + 1) if is_prime(n)]
    result = [n for n in candidate_indices if is_prime(fib(n))]
    return sorted(set(result))
